import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.LX5S0jbT.js";const r=JSON.parse('{"title":"Pi 包","description":"","frontmatter":{},"headers":[],"relativePath":"zh/packages.md","filePath":"zh/packages.md"}'),p={name:"zh/packages.md"};function n(l,s,h,o,d,k){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="pi-包" tabindex="-1">Pi 包 <a class="header-anchor" href="#pi-包" aria-label="Permalink to &quot;Pi 包&quot;">​</a></h1><p>Pi 包（package）将扩展、技能、提示词模板和主题作为一个整体进行安装和分发。当某项定制需要通过 npm 或 git 共享，或多个资源需要捆绑在一起时，使用包。</p><p>包就是一个普通的目录或 npm 包。它可以暴露约定俗成的资源目录、在 <code>package.json</code> 的 <code>pi</code> 键下声明显式路径，并携带自己的运行时依赖。</p><h2 id="安装和管理包" tabindex="-1">安装和管理包 <a class="header-anchor" href="#安装和管理包" aria-label="Permalink to &quot;安装和管理包&quot;">​</a></h2><p>从 npm、git 或本地路径安装：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm:@example/pi-tools@1.0.0</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> git:github.com/example/pi-tools@v1</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> ./local-package</span></span></code></pre></div><p><code>pi list</code> 显示已配置的包。使用 <code>pi remove &lt;source&gt;</code> 移除一个包，<code>pi update --extensions</code> 调整包的安装状态。所有包命令和选项见<a href="./cli.html#package-commands">命令行</a>。</p><p>如果已配置的包在启动时安装失败，例如 npm 无法访问 registry，Pi 会发出警告、跳过该包的资源并继续运行。Pi 会在下次启动或 <code>/reload</code> 时重试安装。<code>pi install</code> 和 <code>pi update --extensions</code> 仍会报告失败并以非零码退出。</p><p>个人安装写入 <code>~/.pi/agent/settings.json</code>。添加 <code>--local</code> 或 <code>-l</code> 可将包声明写入 <code>.pi/settings.json</code>。Pi 只在授予项目信任后才读取该文件中的声明。</p><p>项目包只有在项目信任判定完成后才会安装和加载。包可以执行扩展代码，也可能包含指示模型运行程序的技能。安装第三方包之前请先审查其源码。授予项目信任之前请先审查项目包声明。</p><p>使用 <code>--extension</code> 或 <code>-e</code> 可以单次运行试用某个包，而不将其加入设置：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">pi</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> -e</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> npm:@example/pi-tools</span></span></code></pre></div><h2 id="选择来源" tabindex="-1">选择来源 <a class="header-anchor" href="#选择来源" aria-label="Permalink to &quot;选择来源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>来源</th><th>示例</th><th>行为</th></tr></thead><tbody><tr><td>npm</td><td><code>npm:@example/pi-tools@1.0.0</code></td><td>安装在 Pi 的 npm 目录下</td></tr><tr><td>git</td><td><code>git:github.com/example/pi-tools@v1</code></td><td>克隆并对齐到所选 ref</td></tr><tr><td>URL</td><td><code>https://github.com/example/pi-tools</code></td><td>视为 git 来源</td></tr><tr><td>本地</td><td><code>./pi-tools</code></td><td>从解析后的路径直接加载，不复制</td></tr></tbody></table><p>带版本的 npm 规格会被固定（pin）。git 的 tag 和 commit 同样被固定；包更新只会调整检出状态，不会移动已配置的 ref。</p><p>相对本地路径相对于包含它的设置文件解析。文件路径加载一个扩展。目录遵循正常的包发现规则。</p><h2 id="创建包" tabindex="-1">创建包 <a class="header-anchor" href="#创建包" aria-label="Permalink to &quot;创建包&quot;">​</a></h2><p>最简单的包使用约定目录：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>my-pi-package/</span></span>
<span class="line"><span>├── package.json</span></span>
<span class="line"><span>├── extensions/</span></span>
<span class="line"><span>├── skills/</span></span>
<span class="line"><span>├── prompts/</span></span>
<span class="line"><span>└── themes/</span></span></code></pre></div><p>没有 <code>pi</code> 清单时，Pi 会从这些目录中发现 TypeScript 和 JavaScript 扩展、技能目录、Markdown 提示词和 JSON 主题。</p><p>当资源位于其他位置或需要过滤时，使用显式清单：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;name&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;my-pi-package&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;keywords&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;pi-package&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;pi&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;extensions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./src/extension.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;skills&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./resources/skills&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;prompts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./resources/prompts/*.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;themes&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;./resources/themes/*.json&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>路径相对于包根目录。数组支持 glob 模式和排除项。当 glob 遍历无法发现点前缀或符号链接的资源根目录时，直接列出它们。</p><p><code>pi-package</code> 关键字使 npm 包有资格出现在 <a href="https://pi.dev/packages" target="_blank" rel="noreferrer">Pi 包画廊</a>中。可选的 <code>pi.image</code> 和 <code>pi.video</code> 字段用于添加画廊预览。</p><h2 id="声明依赖" tabindex="-1">声明依赖 <a class="header-anchor" href="#声明依赖" aria-label="Permalink to &quot;声明依赖&quot;">​</a></h2><p>将扩展导入的运行时包放入 <code>dependencies</code>。Pi 在安装 npm 或 git 来源的包时会安装其依赖。</p><p>Pi 会向扩展和技能提供以下包：</p><ul><li><code>@earendil-works/pi-ai</code></li><li><code>@earendil-works/pi-agent-core</code></li><li><code>@earendil-works/pi-coding-agent</code></li><li><code>@earendil-works/pi-tui</code></li><li><code>typebox</code></li></ul><p>将上述宿主提供的包以 <code>&quot;*&quot;</code> 范围声明在 <code>peerDependencies</code> 中，并且不要打包它们。Pi 会抑制受管 npm 包以及通过 npm、pnpm 或 Bun 安装的 git 包的自动 peer 安装。本地包不会被安装或修改，因此其依赖树仍由包作者负责。</p><p>不要将宿主提供的包列入 <code>dependencies</code>。物理副本可能在编译后的 ESM 中绕过 Pi 的扩展模块映射，导致重复的类、注册表和初始化工作。Pi 检测到这种清单配置时会报告扩展警告。作为依赖使用的其他 Pi 包必须包含在发布的 tarball 中，并通过其 <code>node_modules</code> 资源路径引用。</p><p>已安装的包以独立的模块根加载。不要依赖两个包共享同一个依赖实例，也不要依赖一个包解析另一个包未声明的依赖。</p><h2 id="选择包资源" tabindex="-1">选择包资源 <a class="header-anchor" href="#选择包资源" aria-label="Permalink to &quot;选择包资源&quot;">​</a></h2><p>设置中的对象形式可以缩小从包中加载的资源：</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;packages&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;source&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;npm:@example/pi-tools&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;extensions&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;extensions/*.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;!extensions/legacy.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;skills&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [],</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;prompts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: [</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;prompts/review.md&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>对每种资源类型：</p><ul><li>省略该属性以加载包允许的全部资源。</li><li>使用 <code>[]</code> 表示不加载该类型。</li><li>使用 <code>!pattern</code> 排除 glob 匹配项。</li><li>使用 <code>+path</code> 精确包含一个允许的路径。</li><li>使用 <code>-path</code> 精确排除一个路径。</li></ul><p>过滤器只会收窄包清单，不会暴露包本身未声明的资源。</p><p>运行 <code>pi config</code> 可以启用或禁用发现的资源和 Pi 内置扩展。它从个人配置开始；按 Tab 切换作用域，或运行 <code>pi config --local</code> 以项目覆盖开始。</p><h2 id="作用域与标识" tabindex="-1">作用域与标识 <a class="header-anchor" href="#作用域与标识" aria-label="Permalink to &quot;作用域与标识&quot;">​</a></h2><p>同一个包可以同时出现在个人设置和项目设置中。项目条目通常会替换个人条目。设置 <code>autoload: false</code> 时，项目条目改为作为对个人包的过滤增量。</p><p>Pi 通过包名标识 npm 包，通过不含 ref 的仓库 URL 标识 git 包，通过解析后的绝对路径标识本地包。这样可以防止同一个包通过等价声明被加载两次。</p><p>在打包之前，先用<a href="./extensions.html">扩展</a>、<a href="./skills.html">技能</a>、<a href="./prompt-templates.html">提示词模板</a>和<a href="./themes.html">主题</a>设计好每个资源。</p>`,42)])])}const g=i(p,[["render",n]]);export{r as __pageData,g as default};
